style.css:
@-moz-document domain("youtube.com") {
/* ========== 1. BOLINHA DA BARRA = MARGARIDA ========== */
  .ytp-scrubber-button {
    background: url("data:image/png;base64,") center / contain no-repeat !important;
    background-color: transparent !important;
    border-radius: 0 !important;
    width: 28px !important;
    height: 28px !important;
    margin-left: -14px !important;
    margin-top: -10px !important;
    animation: margarida-giro 6s linear infinite;
  }
  @keyframes margarida-giro {
    to { rotate: 360deg; }
  }

  /* ========== 3. LOGO DO YOUTUBE = LÓTUS ========== */
  ytd-topbar-logo-renderer #logo-icon {
    width: 48px !important;
    height: 28px !important;
    background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 60'><g fill='%23f8bbd0' stroke='%23c2185b' stroke-width='2'><ellipse cx='50' cy='32' rx='9' ry='24' transform='rotate(-65 50 56)'/><ellipse cx='50' cy='32' rx='9' ry='24' transform='rotate(65 50 56)'/><ellipse cx='50' cy='32' rx='10' ry='25' transform='rotate(-35 50 56)'/><ellipse cx='50' cy='32' rx='10' ry='25' transform='rotate(35 50 56)'/><ellipse cx='50' cy='30' rx='10' ry='26' fill='%23f48fb1'/></g></svg>") center / contain no-repeat !important;
  }
  ytd-topbar-logo-renderer #logo-icon svg,
  ytd-topbar-logo-renderer #logo-icon * {
    visibility: hidden !important;
  }

  /* ========== 4. BOTÃO DE CONFIGURAÇÕES = GIRASSOL ========== */
  .ytp-settings-button {
    background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='-50 -50 100 100'><g fill='%23f5c518' stroke='%23d99a00' stroke-width='3'><ellipse cy='-30' rx='11' ry='19'/><ellipse cy='-30' rx='11' ry='19' transform='rotate(45)'/><ellipse cy='-30' rx='11' ry='19' transform='rotate(90)'/><ellipse cy='-30' rx='11' ry='19' transform='rotate(135)'/><ellipse cy='-30' rx='11' ry='19' transform='rotate(180)'/><ellipse cy='-30' rx='11' ry='19' transform='rotate(225)'/><ellipse cy='-30' rx='11' ry='19' transform='rotate(270)'/><ellipse cy='-30' rx='11' ry='19' transform='rotate(315)'/></g><circle r='18' fill='%235a3a12' stroke='%233b2408' stroke-width='3'/></svg>") center / 55% no-repeat !important;
  }
  .ytp-settings-button svg {
    display: none !important;
  }
}
